    { const char * tb_v877 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v877; }
    { const char * tb_v878 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v878; }
    { const char * tb_v879 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v879; }
    { const char * tb_v880 = "TB_COLD static void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v880; }
    { const char * tb_v881 = "    fflush(stdout);\n"; *(const char * *)tb_grow(v_lines) = tb_v881; }
