    { const char * tb_v890 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v890; }
    { const char * tb_v891 = "// ---------- падение по памяти: понятное сообщение вместо «Segmentation fault» ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v891; }
    { const char * tb_v892 = "// Чаще всего это стек: функция зовёт себя слишком глубоко. Обработчик работает\n"; *(const char * *)tb_grow(v_lines) = tb_v892; }
    { const char * tb_v893 = "// на своём маленьком стеке (sigaltstack), потому что основной уже кончился.\n"; *(const char * *)tb_grow(v_lines) = tb_v893; }
    { const char * tb_v894 = "#include <signal.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v894; }
