    { const char * tb_v966 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
