    { const char * tb_v1949 = "// ---------- obj: память пачкой ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1949; }
    { const char * tb_v1950 = "// obj никогда не отдают по одному (нет free), поэтому их не надо брать через malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1950; }
    { const char * tb_v1951 = "// поштучно: берём кусок на тысячи объектов и раздаём подряд. Быстрее, и соседние\n"; *(const char * *)tb_grow(v_lines) = tb_v1951; }
    { const char * tb_v1952 = "// объекты лежат рядом в памяти. Внутри temp и шага цикла — как раньше, из временной памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v1952; }
