    { const char * tb_v1968 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1968; }
    { const char * tb_v1969 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1969; }
    { const char * tb_v1970 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1970; }
